<script setup lang="ts">
import { ArrowLeft, ArrowRight, Plus, Sunny } from '@element-plus/icons-vue'
import { computed } from 'vue'
const props = defineProps<{ dates: string[]; modelValue: string }>()
const emit = defineEmits<{ 'update:modelValue': [day: string]; add: []; minimal: [] }>()
const index = computed(() => props.dates.indexOf(props.modelValue))
const label = computed(() => { const day = new Date(`${props.modelValue}T00:00:00`); return Number.isNaN(day.getTime()) ? '' : `${props.modelValue.slice(5, 7)}月${props.modelValue.slice(8)}日（${['周日','周一','周二','周三','周四','周五','周六'][day.getDay()]}）` })
function move(step: number) { const day = props.dates[index.value + step]; if (day) emit('update:modelValue', day) }
function keydown(event: KeyboardEvent) { if (event.key === 'ArrowRight' || event.key === 'ArrowLeft') { event.preventDefault(); move(event.key === 'ArrowRight' ? 1 : -1) } }
</script>
<template><div class="day-toolbar"><div class="day-tabs" role="tablist" aria-label="旅行日期" @keydown="keydown"><button v-for="(day, i) in dates" :id="`day-${day}`" :key="day" role="tab" :aria-selected="day === modelValue" aria-controls="daily-timeline" :tabindex="day === modelValue ? 0 : -1" :class="{ selected: day === modelValue }" @click="emit('update:modelValue', day)">第 {{ i + 1 }} 天</button></div><button class="icon-button add-day-item" aria-label="添加行程项" title="为当天添加行程项" @click="emit('add')"><el-icon><Plus /></el-icon></button><button class="minimal-day" aria-label="极简规划这一天" title="只为这一天做一份极简计划：两处景点、三餐，且不与其他天重复。点击后请求会先写进 AI Copilot，你可以改完再发送。" @click="emit('minimal')"><el-icon><Sunny /></el-icon>极简规划这一天</button><div class="date-control"><button class="icon-button" aria-label="前一天" :disabled="index <= 0" @click="move(-1)"><el-icon><ArrowLeft /></el-icon></button><time :datetime="modelValue">{{ label }}</time><button class="icon-button" aria-label="后一天" :disabled="index >= dates.length - 1" @click="move(1)"><el-icon><ArrowRight /></el-icon></button></div></div></template>
<style scoped>.day-toolbar{display:flex;gap:8px;align-items:center;border-bottom:1px solid var(--border);min-height:51px;padding:0 14px}.day-tabs{display:flex;align-self:stretch;min-width:0;overflow:auto;scrollbar-width:thin}.day-tabs>button{position:relative;white-space:nowrap;border:0;background:none;color:#7a8199;padding:13px 12px;font-size:15px;cursor:pointer}.day-tabs>button:first-child{padding-left:5px}.day-tabs>button.selected{color:var(--primary);font-weight:650}.day-tabs>button.selected:after{content:'';height:3px;position:absolute;bottom:0;left:9px;right:9px;border-radius:3px;background:var(--primary)}.add-day-item{border:1px solid var(--border);font-size:13px;width:25px;height:25px;flex-shrink:0}.date-control{margin-left:auto;display:flex;align-items:center;white-space:nowrap;font-size:11px;gap:1px}.minimal-day{display:inline-flex;align-items:center;gap:4px;flex-shrink:0;border:1px solid var(--border);border-radius:6px;background:#fff;color:#4a5169;font-size:12px;font-weight:500;padding:3px 8px;cursor:pointer;white-space:nowrap}.minimal-day:hover{border-color:var(--primary);color:var(--primary)}.date-control .icon-button{font-size:11px;width:22px;height:27px}.date-control time{white-space:nowrap}.icon-button:disabled{opacity:.3;cursor:default}@media(max-width:1399px){.day-toolbar{flex-wrap:wrap;gap:0;padding:0 10px}.date-control{font-size:10px}.day-tabs>button{font-size:14px;padding:14px 8px}.add-day-item{margin-left:6px}.date-control time{max-width:110px;overflow:hidden}}@media(max-width:759px){.day-toolbar{flex-wrap:nowrap}.date-control time{display:none}.day-tabs{flex:1}}</style>
